     1→//! The `BeaconProposer` cache stores the proposer indices for some epoch.
     2→//!
     3→//! This cache is keyed by `(epoch, block_root)` where `block_root` is the block root at
     4→//! `end_slot(epoch - 1)`. We make the assertion that the proposer shuffling is identical for all
     5→//! blocks in `epoch` which share the common ancestor of `block_root`.
     6→//!
     7→//! The cache is a fairly unintelligent LRU cache that is not pruned after finality. This makes it
     8→//! very simple to reason about, but it might store values that are useless due to finalization. The
     9→//! values it stores are very small, so this should not be an issue.
    10→
    11→use crate::{BeaconChain, BeaconChainError, BeaconChainTypes};
    12→use fork_choice::ExecutionStatus;
    13→use lru::LruCache;
    14→use once_cell::sync::OnceCell;
    15→use smallvec::SmallVec;
    16→use state_processing::state_advance::partial_state_advance;
    17→use std::cmp::Ordering;
    18→use std::num::NonZeroUsize;
    19→use std::sync::Arc;
    20→use types::non_zero_usize::new_non_zero_usize;
    21→use types::{
    22→    BeaconState, BeaconStateError, ChainSpec, Epoch, EthSpec, Fork, Hash256, Slot, Unsigned,
    23→};
    24→
    25→/// The number of sets of proposer indices that should be cached.
    26→const CACHE_SIZE: NonZeroUsize = new_non_zero_usize(16);
    27→
    28→/// This value is fairly unimportant, it's used to avoid heap allocations. The result of it being
    29→/// incorrect is non-substantial from a consensus perspective (and probably also from a
    30→/// performance perspective).
    31→pub const TYPICAL_SLOTS_PER_EPOCH: usize = 32;
    32→
    33→/// For some given slot, this contains the proposer index (`index`) and the `fork` that should be
    34→/// used to verify their signature.
    35→pub struct Proposer {
    36→    pub index: usize,
    37→    pub fork: Fork,
    38→}
    39→
    40→/// The list of proposers for some given `epoch`, alongside the `fork` that should be used to verify
    41→/// their signatures.
    42→pub struct EpochBlockProposers {
    43→    /// The epoch to which the proposers pertain.
    44→    pub(crate) epoch: Epoch,
    45→    /// The fork that should be used to verify proposer signatures.
    46→    pub(crate) fork: Fork,
    47→    /// A list of length `T::EthSpec::slots_per_epoch()`, representing the proposers for each slot
    48→    /// in that epoch.
    49→    ///
    50→    /// E.g., if `self.epoch == 1`, then `self.proposers[0]` contains the proposer for slot `32`.
    51→    pub(crate) proposers: SmallVec<[usize; TYPICAL_SLOTS_PER_EPOCH]>,
    52→}
    53→
    54→/// A cache to store the proposers for some epoch.
    55→///
    56→/// See the module-level documentation for more information.
    57→pub struct BeaconProposerCache {
    58→    cache: LruCache<(Epoch, Hash256), Arc<OnceCell<EpochBlockProposers>>>,
    59→}
    60→
    61→impl Default for BeaconProposerCache {
    62→    fn default() -> Self {
    63→        Self {
    64→            cache: LruCache::new(CACHE_SIZE),
    65→        }
    66→    }
    67→}
    68→
    69→impl BeaconProposerCache {
    70→    /// If it is cached, returns the proposer for the block at `slot` where the block has the
    71→    /// ancestor block root of `shuffling_decision_block` at `end_slot(slot.epoch() - 1)`.
    72→    pub fn get_slot<E: EthSpec>(
    73→        &mut self,
    74→        shuffling_decision_block: Hash256,
    75→        slot: Slot,
    76→    ) -> Option<Proposer> {
    77→        let epoch = slot.epoch(E::slots_per_epoch());
    78→        let key = (epoch, shuffling_decision_block);
    79→        let cache_opt = self.cache.get(&key).and_then(|cell| cell.get());
    80→        if let Some(cache) = cache_opt {
    81→            // This `if` statement is likely unnecessary, but it feels like good practice.
    82→            if epoch == cache.epoch {
    83→                cache
    84→                    .proposers
    85→                    .get(slot.as_usize() % E::SlotsPerEpoch::to_usize())
    86→                    .map(|&index| Proposer {
    87→                        index,
    88→                        fork: cache.fork,
    89→                    })
    90→            } else {
    91→                None
    92→            }
    93→        } else {
    94→            None
    95→        }
    96→    }
    97→
    98→    /// As per `Self::get_slot`, but returns all proposers in all slots for the given `epoch`.
    99→    ///
   100→    /// The nth slot in the returned `SmallVec` will be equal to the nth slot in the given `epoch`.
   101→    /// E.g., if `epoch == 1` then `smallvec[0]` refers to slot 32 (assuming `SLOTS_PER_EPOCH ==
   102→    /// 32`).
   103→    pub fn get_epoch<E: EthSpec>(
   104→        &mut self,
   105→        shuffling_decision_block: Hash256,
   106→        epoch: Epoch,
   107→    ) -> Option<&SmallVec<[usize; TYPICAL_SLOTS_PER_EPOCH]>> {
   108→        let key = (epoch, shuffling_decision_block);
   109→        self.cache
   110→            .get(&key)
   111→            .and_then(|cache_once_cell| cache_once_cell.get().map(|proposers| &proposers.proposers))
   112→    }
   113→
   114→    /// Returns the `OnceCell` for the given `(epoch, shuffling_decision_block)` key,
   115→    /// inserting an empty one if it doesn't exist.
   116→    ///
   117→    /// The returned `OnceCell` allows the caller to initialise the value externally
   118→    /// using `get_or_try_init`, enabling deferred computation without holding a mutable
   119→    /// reference to the cache.
   120→    pub fn get_or_insert_key(
   121→        &mut self,
   122→        epoch: Epoch,
   123→        shuffling_decision_block: Hash256,
   124→    ) -> Arc<OnceCell<EpochBlockProposers>> {
   125→        let key = (epoch, shuffling_decision_block);
   126→        self.cache
   127→            .get_or_insert(key, || Arc::new(OnceCell::new()))
   128→            .clone()
   129→    }
   130→
   131→    /// Insert the proposers into the cache.
   132→    ///
   133→    /// See `Self::get` for a description of `shuffling_decision_block`.
   134→    ///
   135→    /// The `fork` value must be valid to verify proposer signatures in `epoch`.
   136→    pub fn insert(
   137→        &mut self,
   138→        epoch: Epoch,
   139→        shuffling_decision_block: Hash256,
   140→        proposers: Vec<usize>,
   141→        fork: Fork,
   142→    ) -> Result<(), BeaconStateError> {
   143→        let key = (epoch, shuffling_decision_block);
   144→        if !self.cache.contains(&key) {
   145→            let epoch_proposers = EpochBlockProposers {
   146→                epoch,
   147→                fork,
   148→                proposers: proposers.into(),
   149→            };
   150→            self.cache
   151→                .put(key, Arc::new(OnceCell::with_value(epoch_proposers)));
   152→        }
   153→
   154→        Ok(())
   155→    }
   156→}
   157→
   158→/// Compute the proposer duties using the head state without cache.
   159→pub fn compute_proposer_duties_from_head<T: BeaconChainTypes>(
   160→    request_epoch: Epoch,
   161→    chain: &BeaconChain<T>,
   162→) -> Result<(Vec<usize>, Hash256, ExecutionStatus, Fork), BeaconChainError> {
   163→    // Atomically collect information about the head whilst holding the canonical head `Arc` as
   164→    // short as possible.
   165→    let (mut state, head_state_root, head_block_root) = {
   166→        let head = chain.canonical_head.cached_head();
   167→        // Take a copy of the head state.
   168→        let head_state = head.snapshot.beacon_state.clone();
   169→        let head_state_root = head.head_state_root();
   170→        let head_block_root = head.head_block_root();
   171→        (head_state, head_state_root, head_block_root)
   172→    };
   173→
   174→    let execution_status = chain
   175→        .canonical_head
   176→        .fork_choice_read_lock()
   177→        .get_block_execution_status(&head_block_root)
   178→        .ok_or(BeaconChainError::HeadMissingFromForkChoice(head_block_root))?;
